<script setup lang="ts">import{onMounted,reactive}from'vue';import{NButton,NForm,NFormItem,NInput,useMessage}from'naive-ui';import{api}from'../api';const message=useMessage(),form=reactive<Record<string,string>>({});onMounted(async()=>Object.assign(form,await api.get('/settings')));async function save(){try{await api.put('/settings',form);message.success('设置已保存，前台立即生效')}catch(e:any){message.error(e.message)}}</script>
<template><div class="page-head"><h1>站点设置</h1><n-button type="primary" @click="save">保存全部</n-button></div><n-form class="panel" label-placement="top"><div class="form-grid"><n-form-item label="站点名称"><n-input v-model:value="form['site.title']"/></n-form-item><n-form-item label="副标题"><n-input v-model:value="form['site.subtitle']"/></n-form-item><n-form-item class="wide" label="站点描述"><n-input v-model:value="form['site.description']" type="textarea"/></n-form-item><n-form-item label="备案号"><n-input v-model:value="form['site.icp']"/></n-form-item><n-form-item label="列表每页数量"><n-input v-model:value="form['content.apps_page_size']"/></n-form-item><n-form-item class="wide" label="页脚内容"><n-input v-model:value="form['site.footer']" type="textarea"/></n-form-item><n-form-item class="wide" label="Head 注入"><n-input v-model:value="form['custom.head']" type="textarea"/></n-form-item></div></n-form></template>

